function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }
    g_form.setDisplay('bulk_id.bulk_field_group', false);
    // Display all fields initially
    displayAllFields();

    // Perform amend eligibility check
    var eligbleCheck = new GlideAjax('x_hsb11_mss_c_proc.MSSCustodyAmendUtils');
    eligbleCheck.addParam('sysparm_name', 'evalAmendEligibility');
    eligbleCheck.addParam('sysparm_recOutcome', g_form.getValue('outcome'));
    eligbleCheck.addParam('sysparm_recSysID', g_form.getUniqueValue());
    eligbleCheck.addParam('sysparm_tableName', 'x_hsb11_mss_c_proc_mss_custody_task');
    eligbleCheck.getXMLAnswer(function(check) {
        if (check.toString() === 'true') {
            //MSSCUSTODY-5980 - introduced trade fields on form for amend
            g_form.setDisplay('trade_id.transaction_type', true);
            g_form.setDisplay('trade_id.security_account_type', true);
            g_form.setDisplay('trade_id.securities_account', true);
            g_form.setDisplay('trade_id.account_name', true);
            g_form.setDisplay('trade_id.associated_sub_account', true);
            g_form.setDisplay('trade_id.si_purpose_code', true);
            g_form.setDisplay('trade_id.si_payment_indicator', true);
            g_form.setReadOnly('trade_id.transaction_type', true);
            g_form.setReadOnly('trade_id.security_account_type', true);
            g_form.setReadOnly('trade_id.securities_account', true);
            g_form.setReadOnly('trade_id.account_name', true);
            g_form.setReadOnly('trade_id.associated_sub_account', true);
            g_form.setReadOnly('trade_id.si_purpose_code', true);
            g_form.setReadOnly('trade_id.si_payment_indicator', true);
            //MSSCUSTODY-5980 - introduced trade fields on form for amend
            // Stage-by-stage evaluation
            var transactionType = g_form.getValue('trade_id.transaction_type');

            var getData = g_form.getReference('trade_id', getTradeData);

            function getTradeData(getData) {

                var switchIndicator = getData.switch_indicator.toString()

                //var switchIndicator = g_form.getValue('trade_id.switch_indicator');
                var legacyStatus = g_form.getValue('trade_id.legacy_status');
                var legacyPrevStatus = g_form.getValue('trade_id.legacy_previous_status');

                if (!evaluateStage1(transactionType))
                    return; // Stop if Stage 1 fails
                if (!evaluateStage2(switchIndicator))
                    return; // Stop if Stage 2 fails
                evaluateStage3(legacyStatus, legacyPrevStatus, switchIndicator); // Proceed to Stage 3
                g_form.setReadOnly("bulk_id.security_id_sec_id", true);
                g_form.setReadOnly("bulk_id.amend_switch_account", true);
                g_form.setReadOnly("bulk_id.amend_counterparty_code", true);
            }

        } else {
            // If not eligible, hide all fields
            hideAllFields();
        }

    });
}

//Displays all fields by setting them to visible and editable.
function displayAllFields() {
    var fields = getAllFields();
    fields.forEach(function(field) {
        g_form.setDisplay(field, true);
        g_form.setReadOnly(field, false);
    });
}

//Hides all fields
function hideAllFields() {
    var fields = getAllFields();
    fields.forEach(function(field) {
        g_form.setDisplay(field, false);
    });
}

// Returns a list of all fields.

function getAllFields() {
    return [
        'bulk_id.security_id_sec_id',
        'bulk_id.amend_trade_date',
        'bulk_id.settlement_date',
        'bulk_id.amend_deal_price',
        'bulk_id.amend_deal_currency',
        'bulk_id.amend_settlement_currency',
        'bulk_id.amend_settlement_amount',
        'bulk_id.counterparty_reference',
        'bulk_id.customer_reference',
        'bulk_id.amend_location_code',
        'bulk_id.amend_hmi_indicator',
        'bulk_id.amend_script_hold_indicator',
        'bulk_id.amend_cash_hold_indicator',
        'bulk_id.amend_gdi_indicator',
        'bulk_id.amend_payment_method',
        'bulk_id.amend_switch_indicator',
        'bulk_id.amend_switch_account',
        'bulk_id.amend_counterparty_code',
        'bulk_id.amend_deliverer_custodian_bic_receiver_custodian_bic',
        'bulk_id.amend_seller_bic_buyer_bic',
        'bulk_id.amend_place_of_settlement_bic',
        'bulk_id.amend_suspense_account_number',
        'bulk_id.amend_counterparty_settlement_account_number',
        'bulk_id.amend_convert_to_account_switching',
        'bulk_id.amend_a_c_of_client',
        'bulk_id.amend_charges_ccy',
        'bulk_id.amend_charges_amt',
        'bulk_id.amend_charges_type',
        'bulk_id.amend_nssc',
        'bulk_id.amend_switch_account_ref',
        'bulk_id.amend_counterparty_code_ref',
        'bulk_id.amend_security_id_sec_id_ref',
        'trade_id.transaction_type',
        'trade_id.security_account_type',
        'trade_id.securities_account',
        'trade_id.account_name',
        'trade_id.associated_sub_account',
        'trade_id.si_purpose_code',
        'trade_id.si_payment_indicator'
    ];
}

// Evaluates Stage 1: Based on Transaction Type.
function evaluateStage1(transactionType) {
    var stage1Fields = {
        'bulk_id.amend_deal_price': ['RVP', 'DVP'],
        'bulk_id.amend_deal_currency': ['RVP', 'DVP'],
        'bulk_id.amend_payment_method': ['RVP', 'DVP'],
        'bulk_id.amend_settlement_currency': ['RVP', 'DVP'],
        'bulk_id.amend_settlement_amount': ['RVP', 'DVP'],
        'bulk_id.amend_suspense_account_number': ['RVP', 'DVP'],
        'bulk_id.amend_script_hold_indicator': ['DVP', 'DFP'],
        'bulk_id.amend_cash_hold_indicator': ['RVP'],
        'bulk_id.amend_nssc': ['DVP', 'DFP'],
        'bulk_id.amend_counterparty_settlement_account_number': ['RVP', 'DVP']
    };

    // Track if at least one field is applicable
    var stagePass = false;

    // Iterate over each field and determine visibility based on transactionType
    Object.keys(stage1Fields).forEach(function(field) {
        var applicableTransactionTypes = stage1Fields[field];
        if (applicableTransactionTypes.includes(transactionType)) {
            g_form.setDisplay(field, true); // Show the field if transactionType matches
            stagePass = true; // Mark stage as passed
        } else {
            g_form.setDisplay(field, false); // Hide the field if transactionType does not match
        }
    });

    return stagePass; // Return true if at least one field is applicable, otherwise false
}


function evaluateStage2(switchIndicator) {
    // Configuration for Stage 2 fields switch and non- switch trades
    var stage2Fields = {
        'bulk_id.security_id_sec_id': {
            N: 'show',
            Y: 'show'
        }, // Security ID
        'bulk_id.amend_security_id_sec_id_ref': {
            N: 'show',
            Y: 'show'
        },
        'bulk_id.amend_trade_date': {
            N: 'show',
            Y: 'show'
        }, // Trade Date
        'bulk_id.settlement_date': {
            N: 'show',
            Y: 'show'
        }, // Settlement Date
        'bulk_id.amend_deal_currency': {
            N: 'show',
            Y: 'hide'
        }, // Deal Currency / Price
        'bulk_id.amend_deal_price': {
            N: 'show',
            Y: 'hide'
        },
        'bulk_id.amend_settlement_currency': {
            N: 'show',
            Y: 'show'
        }, // Settlement Currency
        'bulk_id.amend_settlement_amount': {
            N: 'show',
            Y: 'show'
        }, // Settlement Amount
        'bulk_id.counterparty_reference': {
            N: 'show',
            Y: 'hide'
        }, // Counterparty Reference
        'bulk_id.customer_reference': {
            N: 'show',
            Y: 'show'
        }, // Customer Reference
        'bulk_id.amend_location_code': {
            N: 'show',
            Y: 'show'
        }, // Location Code
        'bulk_id.amend_hmi_indicator': {
            N: 'show',
            Y: 'show'
        }, // HMI Indicator
        'bulk_id.amend_script_hold_indicator': {
            N: 'show',
            Y: 'show'
        }, // Scrip Hold Indicator
        'bulk_id.amend_cash_hold_indicator': {
            N: 'show',
            Y: 'show'
        }, // Cash Hold Indicator
        'bulk_id.amend_gdi_indicator': {
            N: 'show',
            Y: 'show'
        }, // GDI Indicator
        'bulk_id.amend_payment_method': {
            'N': 'show',
            'Y': 'hide'
        }, // Payment Method
        'bulk_id.amend_switch_account': {
            N: 'hide',
            Y: 'show'
        }, // Switch Account
        'bulk_id.amend_switch_account_ref': {
            N: 'hide',
            Y: 'show'
        }, // Switch Account
        'bulk_id.amend_suspense_account_number': {
            N: 'hide',
            Y: 'show'
        }, // Suspense Account Number
        'bulk_id.amend_counterparty_code': {
            N: 'show',
            Y: 'hide'
        }, // Counterparty Code
        'bulk_id.amend_counterparty_code_ref': {
            N: 'show',
            Y: 'hide'
        },
        'bulk_id.amend_counterparty_settlement_account_number': {
            N: 'show',
            Y: 'hide'
        }, // Counterparty Settlement Account Number
        'bulk_id.amend_a_c_of_client': {
            N: 'show',
            Y: 'show'
        }, // A/c of Client
        'bulk_id.amend_deliverer_custodian_bic_receiver_custodian_bic': {
            N: 'show',
            Y: 'show'
        }, // Deliverer Custodian (BIC) / Receiver Custodian (BIC)
        'bulk_id.amend_seller_bic_buyer_bic': {
            N: 'show',
            Y: 'show'
        }, // Seller (BIC) / Buyer (BIC)
        'bulk_id.amend_place_of_settlement_bic': {
            N: 'show',
            Y: 'show'
        }, // Place of Settlement (BIC)
        'bulk_id.amend_charges_type': {
            N: 'show',
            Y: 'show'
        }, // Amend Charges Type
        'bulk_id.amend_charges_ccy': {
            N: 'show',
            Y: 'show'
        }, // Amend Charges CCY
        'bulk_id.amend_charges_amt': {
            N: 'show',
            Y: 'show'
        }, // Amend Charges AMT
        'bulk_id.amend_nssc': {
            N: 'show',
            Y: 'show'
        } // NSSC
    };

    Object.keys(stage2Fields).forEach(function(field) {
        var visibility = stage2Fields[field][switchIndicator]; // Get visibility for the current switchIndicator
        if (visibility === 'hide') {
            g_form.setDisplay(field, false); // Hide the field if the value is 'hide'
        }
        // If visibility is 'show', leave the field as is
    });

    return true;
}


function evaluateStage3(legacyStatus, legacyPrevStatus, switchIndicator) {
    // If legacy_status is UNEX, use legacy previous status for handling
    var effectiveStatus = legacyStatus === 'UNEX' ? legacyPrevStatus : legacyStatus;

    // Configuration for Legacy Status and fields to hide
    var legacyStatusConfig = {
        'CODE': [],
        'PRPR': [],
        'PAPP': [],
        'RCP': [],
        'PCON': [],
        'CONF (Non-Switch)': ['bulk_id.security_id_sec_id', 'bulk_id.amend_location_code', 'bulk_id.amend_gdi_indicator'],
        'CONF (Switch)': ['bulk_id.security_id_sec_id', 'bulk_id.amend_deal_price', 'bulk_id.amend_deal_currency', 'bulk_id.amend_location_code', 'bulk_id.amend_gdi_indicator', 'bulk_id.amend_payment_method'],
        'CLRG': ['bulk_id.security_id_sec_id', 'bulk_id.amend_security_id_sec_id_ref', 'bulk_id.amend_deal_price', 'bulk_id.amend_deal_currency', 'bulk_id.amend_location_code', 'bulk_id.amend_gdi_indicator', 'bulk_id.amend_switch_account'],
        'MTCH': ['bulk_id.security_id_sec_id', 'bulk_id.amend_security_id_sec_id_ref', 'bulk_id.amend_deal_price', 'bulk_id.amend_deal_currency', 'bulk_id.amend_settlement_currency', 'bulk_id.amend_settlement_amount', 'bulk_id.customer_reference', 'bulk_id.amend_location_code', 'bulk_id.amend_gdi_indicator', 'bulk_id.amend_switch_account', 'bulk_id.amend_counterparty_code', 'bulk_id.amend_counterparty_code_ref'],
        'STTS': ['bulk_id.security_id_sec_id', 'bulk_id.amend_security_id_sec_id_ref', 'bulk_id.amend_trade_date', 'bulk_id.settlement_date', 'bulk_id.amend_deal_price', 'bulk_id.amend_deal_currency', 'bulk_id.amend_settlement_currency',
            'bulk_id.amend_settlement_amount', 'bulk_id.customer_reference', 'bulk_id.amend_location_code', 'bulk_id.amend_nssc', 'bulk_id.amend_gdi_indicator', 'bulk_id.amend_switch_account', 'bulk_id.amend_switch_account_ref', 'bulk_id.amend_counterparty_code', 'bulk_id.amend_counterparty_code_ref'
        ],
        'STTC': ['bulk_id.security_id_sec_id', 'bulk_id.amend_security_id_sec_id_ref', 'bulk_id.amend_trade_date', 'bulk_id.settlement_date', 'bulk_id.amend_deal_price', 'bulk_id.amend_deal_currency', 'bulk_id.amend_settlement_currency',
            'bulk_id.amend_settlement_amount', 'bulk_id.customer_reference', 'bulk_id.amend_location_code', 'bulk_id.amend_nssc', 'bulk_id.amend_cash_hold_indicator', 'bulk_id.amend_gdi_indicator', 'bulk_id.amend_payment_method',
            'bulk_id.amend_switch_indicator', 'bulk_id.amend_switch_account', 'bulk_id.amend_switch_account_ref', 'bulk_id.amend_counterparty_code', 'bulk_id.amend_deliverer_custodian_bic_receiver_custodian_bic',
            'bulk_id.amend_seller_bic_buyer_bic', 'bulk_id.amend_place_of_settlement_bic', 'bulk_id.amend_suspense_account_number', 'bulk_id.amend_counterparty_code_ref'
        ],
        'Any other status': [
            'bulk_id.security_id_sec_id', 'bulk_id.amend_trade_date', 'bulk_id.settlement_date', 'bulk_id.amend_deal_price', 'bulk_id.amend_deal_currency',
            'bulk_id.amend_settlement_currency', 'bulk_id.amend_settlement_amount', 'bulk_id.counterparty_reference', 'bulk_id.customer_reference', 'bulk_id.amend_location_code',
            'bulk_id.amend_hmi_indicator', 'bulk_id.amend_script_hold_indicator', 'bulk_id.amend_cash_hold_indicator', 'bulk_id.amend_gdi_indicator', 'bulk_id.amend_payment_method',
            'bulk_id.amend_switch_indicator', 'bulk_id.amend_switch_account', 'bulk_id.amend_counterparty_code', 'bulk_id.amend_deliverer_custodian_bic_receiver_custodian_bic',
            'bulk_id.amend_seller_bic_buyer_bic', 'bulk_id.amend_place_of_settlement_bic', 'bulk_id.amend_suspense_account_number', 'bulk_id.amend_counterparty_settlement_account_number',
            'bulk_id.amend_convert_to_account_switching', 'bulk_id.amend_a_c_of_client', 'bulk_id.amend_charges_ccy', 'bulk_id.amend_charges_amt', 'bulk_id.amend_charges_type',
            'bulk_id.amend_nssc', 'bulk_id.amend_counterparty_code_ref', 'bulk_id.amend_security_id_sec_id_ref', 'bulk_id.amend_switch_account_ref'
        ] // Default fields to hide for unmatched statuses
    };

    var columnToConsider = (effectiveStatus === 'CONF' && switchIndicator === 'Y') ? 'CONF (Switch)' :
        (effectiveStatus === 'CONF' && switchIndicator === 'N') ? 'CONF (Non-Switch)' :
        effectiveStatus; // For other legacy statuses (e.g., STTC, STTS), use the effectiveStatus directly

    // Check if the columnToConsider exists in the configuration
    if (!legacyStatusConfig[columnToConsider]) {
        columnToConsider = 'Any other status'; // Consider 'Any other status' if the status is not found
    }

    // Get the fields to make non-editable
    var fieldsToMakeNonEditable = legacyStatusConfig[columnToConsider];

    // Make the fields non-editable
    fieldsToMakeNonEditable.forEach(function(field) {
        g_form.setReadOnly(field, true);
    });
}
